def entropy(p, eps=1e-12):
    p = np.clip(p, eps, 1)
    return -np.sum(p * np.log2(p))

def cross_entropy(p, q, eps=1e-12):
    q = np.clip(q, eps, 1)
    return -np.sum(p * np.log2(q))

def kl_divergence(p, q, eps=1e-12):
    p, q = np.clip(p, eps, 1), np.clip(q, eps, 1)
    return np.sum(p * np.log2(p / q))

