import numpy as np

def gini(y):
    if len(y) == 0: return 0.0
    p = np.bincount(y) / len(y)
    return 1 - (p ** 2).sum()

def best_split(X, y):
    n, d = X.shape
    parent = gini(y)
    best = (0.0, None, None)                     # (gain, feature, threshold)
    for f in range(d):
        for thr in np.unique(X[:, f]):
            left = X[:, f] <= thr
            if left.sum() == 0 or left.sum() == n: continue
            child = (left.sum()*gini(y[left]) + (~left).sum()*gini(y[~left])) / n
            gain = parent - child
            if gain > best[0]:
                best = (gain, f, thr)
    return best                                   # recurse on each side with this split

