def quantize(w, bits=8):
    s = np.abs(w).max() / (2**(bits-1) - 1)
    q = np.round(w / s).clip(-(2**(bits-1)), 2**(bits-1)-1)
    return q, s          # store q (int) + s (scale)

def chunk(text, size=400, overlap=80):
