import numpy as np

def psi(expected, actual, bins=10):
    e, _ = np.histogram(expected, bins); a, _ = np.histogram(actual, bins)
    e = e/e.sum()+1e-6; a = a/a.sum()+1e-6
    return np.sum((a - e) * np.log(a / e))
